SELECT ca.code AS carrier, p.code AS product, o.name AS orig, d.name AS dest, ds.standard_time, ds.time_unit, ds.cl_first_mile_time, ds.cl_last_mile_time, ds.id FROM public.delivery_standards ds JOIN public.carriers ca ON ca.id = ds.carrier_id JOIN public.products p ON p.id = ds.product_id JOIN public.cities o ON o.id = ds.origin_city_id JOIN public.cities d ON d.id = ds.destination_city_id WHERE ds.account_id = 'f4d823d2-93e6-4755-9a89-9da87e7fa86e' ORDER BY 1,2,3,4;
